function toUrl(svg) {
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

icons.svg = (name) => icons[name] || "";
icons.url = (name) => (icons[name] ? toUrl(icons[name]) : "");

// Auto-inject CSS mask rules into the document
if (typeof document !== "undefined") {
  if (typeof window !== "undefined") window.icons = icons;
  if (!document.getElementById("kancamu-icons")) {
    const style = document.createElement("style");
    style.id = "kancamu-icons";
    const vars = [];
    const classes = [];
    for (const [name, svg] of Object.entries(icons)) {
      if (typeof svg === "string") {
        const u = toUrl(svg);
        vars.push(`  --icon-${name}: ${u};`);
        classes.push(`.icon-${name}, .glyph.${name} { --icon: var(--icon-${name}); }`);
      }
    }
    style.textContent = [
      ":root {",
      vars.join("\n"),
      "}",
      classes.join("\n"),
      `
.glyph.theme { --icon: var(--icon-sun); }
:root[data-theme="light"] .glyph.theme { --icon: var(--icon-moon); }
.glyph.error { --icon: var(--icon-alert); }
input[type="checkbox"]:checked::after {
  -webkit-mask: var(--icon-check) center / contain no-repeat;
  mask: var(--icon-check) center / contain no-repeat;
}
select { background-image: var(--icon-chevron-down-white); }
[data-theme="light"] select { background-image: var(--icon-chevron-down-black); }
.alert-info > .icon { -webkit-mask-image: var(--icon-info); mask-image: var(--icon-info); }
.alert-warning > .icon { -webkit-mask-image: var(--icon-warning); mask-image: var(--icon-warning); }
.alert-error > .icon { -webkit-mask-image: var(--icon-alert); mask-image: var(--icon-alert); }
.upload-drop > .icon { -webkit-mask-image: var(--icon-upload); mask-image: var(--icon-upload); }
`
    ].join("\n\n");
    (document.head || document.documentElement).appendChild(style);
  }
}

/* ============================================================
   cleanup.js — delete obsolete localStorage / DB / cache keys
   ============================================================ */
// Deletes what an older version of the code left in this browser and that the code of today does not use any more.
// The apps of Kancamu, muOS, and the apps of ArtCraft all run on one origin and share its localStorage, its databases, and its caches, so this file never deletes
// "what it does not know": it deletes the names that are listed here, and only those. A name is added to a list when the code stops using it:
//   - the key of localStorage that is not read or written by any app any more        (LOCAL_KEYS)
//   - the database of IndexedDB or the cache of Cache Storage that no app opens now  (DATABASES, CACHES)
// What the code of today uses is not here: theme, lang, account, <app>.settings, lingomu.progress, mujs.progress, drivemu.view, muai.autoload, muai.seen.<model>,
// the database "muai", and the cache "transformers-cache". (A token that is not of the sign-in with GitHub is deleted by assets/js/account.js.)
(() => {
    const LOCAL_KEYS = [
        "drivemu.accounts.v2",   // the accounts of Drivemu before the shared sign-in: it kept personal tokens
        "drivemu.session.v1",    // the session of Drivemu before the shared sign-in
        "muai.model",            // the chosen model of muAI, now in "muai.settings"
        "muai.sideWidth",        // the width of the sidebar of muAI, now in "muai.settings"
        "murmbg.settings",       // the settings of muRMBG, which is now Picmu ("picmu.settings")
    ];
    const DATABASES = [];        // the names of IndexedDB databases
    const CACHES = [];           // the names of Cache Storage caches

    for (const key of LOCAL_KEYS) {
        try {
            if (localStorage.getItem(key) !== null) localStorage.removeItem(key);
        } catch {}
    }
    for (const name of DATABASES) {
        try {
            indexedDB.deleteDatabase(name);
        } catch {}
    }
    for (const name of CACHES) {
        try {
            caches.delete(name);
        } catch {}
    }
})();


/* ============================================================
   url.js — window.urlState: query-string state for each app
   ============================================================ */
// Where an app keeps what is on its screen, so a reload shows the same thing: the address of the page (its query string).
// An app reads it when it starts and writes it when the user changes something; it keeps only what is not the first value, so the address of a fresh page is clean.
//   const folder = urlState.get("path");                  the text of a parameter, or "" when it is not there
//   urlState.set({ path: "Images", view: "", q: "cat" }); writes the parameters that are given; "", null, undefined, and false take a parameter away
// The apps of Kancamu open in frames of the main site: the address of the frame is not the address that the user reloads, so every change is also told to the main site
// (it keeps the query string of each tab in its own address), and the main site opens the frame with it the next time. An app that is not in a frame only has its own address.
// The history is not filled: the address is replaced, not added to.
(() => {
    const read = () => new URLSearchParams(location.search);

    window.urlState = {
        get(name) {
            return read().get(name) || "";
        },

        // The parameters that are given, as an object ({ name: value }); the others stay as they are.
        set(values) {
            const params = read();
            for (const [name, value] of Object.entries(values)) {
                if (value === "" || value === null || value === undefined || value === false) params.delete(name);
                else params.set(name, String(value));
            }
            const search = params.toString();
            if (search === location.search.slice(1)) return;
            history.replaceState(null, "", location.pathname + (search ? `?${search}` : "") + location.hash);
            if (window.parent !== window) window.parent.postMessage({ type: "kancamu:url", search }, location.origin);
        },
    };
})();


/* ============================================================
   i18n.js — window.i18n: language support
   ============================================================ */
// Language support shared by every app (except muOS and ArtCraft).
// An app keeps its texts in its own data.js:
//   export default { "name": { "en-US": "..." }, "languages": [{ "code", "name", "dir" }], "ui": { "key": { "en-US": "...", ... } } }
// The rest of the data of the app is in the same file too (the projects of the main website, the models of muAI, the file types of Drivemu): app.js reads it from i18n.data.
// Mark elements in the HTML with data-i18n (text), data-i18n-html (text with <b>/<i>, from our own data.js),
// data-i18n-title, data-i18n-placeholder, or data-i18n-label (aria-label), then call i18n.load().
// A tag kit-* (assets/js/components.js) takes a text for any of its attributes the same way: data-i18n-heading="key" gives heading the text of the key.
(() => {
    // assets/data/brand.js is in the folder data, beside the folder of this script. The name of the brand and its highlighted word are written there and nowhere else.
    const BRAND = new URL("../data/brand.js", import.meta.url).href;
    const FALLBACK = "en-US";
    const KEY = "lang";
    const listeners = [];

    const i18n = {
        lang: FALLBACK,
        languages: [],
        ui: {},
        data: null,
        brand: { name: "", highlight: "" },

        // Loads data.js, picks the language, and applies it to the page.
        async load(url = "data.js") {
            const module = await import(new URL(url, document.baseURI).href);
            this.data = module.default;
            await this.fillBrand();
            this.languages = this.data.languages || [];
            this.ui = this.data.ui || {};
            this.lang = this.resolve();
            this.applyBrandColour();
            this.apply();
            return this.data;
        },

        // The colour of the app (brandColor in its data.js, taken from its icon) is --brand, and the colour of the text on it is --brand-ink:
        // white when it reads well on that colour (a contrast of 3 or more), else dark.
        applyBrandColour() {
            const hex = this.data?.brandColor;
            if (!/^#[0-9a-f]{6}$/i.test(hex || "")) return;
            const channel = (index) => {
                const value = parseInt(hex.slice(1 + index * 2, 3 + index * 2), 16) / 255;
                return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
            };
            const luminance = 0.2126 * channel(0) + 0.7152 * channel(1) + 0.0722 * channel(2);
            const root = document.documentElement.style;
            root.setProperty("--brand", hex);
            root.setProperty("--brand-ink", 1.05 / (luminance + 0.05) >= 3 ? "var(--white)" : "var(--black)");
        },

        // Every text of data.js that says {brand} gets the name of the brand, and {highlight} its highlighted word.
        async fillBrand() {
            try {
                this.brand = (await import(BRAND)).default;
            } catch {}
            const escape = (text) => JSON.stringify(text || "").slice(1, -1);
            this.data = JSON.parse(
                JSON.stringify(this.data)
                    .replaceAll("{highlight}", escape(this.brand.highlight))
                    .replaceAll("{brand}", escape(this.brand.name))
            );
        },

        sameBase(codes, lang) {
            const base = lang.split("-")[0];
            return codes.find((code) => code.split("-")[0] === base);
        },

        // Saved choice, then the browser language, then English.
        resolve() {
            const codes = this.languages.map((language) => language.code);
            let saved = null;
            try {
                saved = localStorage.getItem(KEY);
            } catch {}
            if (codes.includes(saved)) return saved;
            return codes.includes(navigator.language)
                ? navigator.language
                : this.sameBase(codes, navigator.language) || FALLBACK;
        },

        // Picks the text for the current language out of { "en-US": "...", "zh-CN": "..." }.
        pick(texts) {
            if (!texts) return "";
            const sameBase = this.sameBase(Object.keys(texts), this.lang);
            return texts[this.lang] || texts[sameBase] || texts[FALLBACK] || Object.values(texts)[0] || "";
        },

        // Translates a key from data.js "ui". {name} placeholders are filled from params.
        t(key, params = {}) {
            const text = this.ui[key] ? this.pick(this.ui[key]) : key;
            return text.replace(/\{(\w+)\}/g, (_, name) => params[name] ?? "");
        },

        // Sets lang and dir on the page, the title, and every marked element.
        apply(root = document) {
            const language = this.languages.find((item) => item.code === this.lang);
            document.documentElement.lang = this.lang;
            document.documentElement.dir = language?.dir || "ltr";
            if (this.data?.name) document.title = this.pick(this.data.name);
            if (root === document) window.components?.refreshTexts?.();   // the tags kit-* that show a text of assets/data/kit.js
            root.querySelectorAll("[data-i18n]").forEach((element) => {
                element.textContent = this.t(element.dataset.i18n);
            });
            root.querySelectorAll("[data-i18n-html]").forEach((element) => {
                element.innerHTML = this.t(element.dataset.i18nHtml);
            });
            root.querySelectorAll("[data-i18n-title]").forEach((element) => {
                element.title = this.t(element.dataset.i18nTitle);
            });
            root.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
                element.placeholder = this.t(element.dataset.i18nPlaceholder);
            });
            root.querySelectorAll("[data-i18n-label]").forEach((element) => {
                element.setAttribute("aria-label", this.t(element.dataset.i18nLabel));
            });
        },

        // Changes the language, remembers it, and tells the listeners.
        set(code) {
            if (!this.languages.some((language) => language.code === code)) return;
            this.lang = code;
            try {
                localStorage.setItem(KEY, code);
            } catch {}
            this.apply();
            document.querySelectorAll("select.language").forEach((select) => (select.value = code));
            listeners.forEach((listener) => listener(code));
        },

        // Fills every select.language with the languages and keeps them in sync.
        selects() {
            document.querySelectorAll("select.language").forEach((select) => {
                select.replaceChildren(
                    ...this.languages.map((language) => {
                        const option = document.createElement("option");
                        option.value = language.code;
                        option.textContent = language.name;
                        return option;
                    })
                );
                select.value = this.lang;
                select.onchange = () => this.set(select.value);
            });
        },

        // Runs fn after every language change, for text that app.js builds itself.
        onChange(fn) {
            listeners.push(fn);
        },

        // Formats a size, a date, or a number in the current language.
        number(value, options) {
            return new Intl.NumberFormat(this.lang, options).format(value);
        },
        date(value, options) {
            return new Date(value).toLocaleDateString(this.lang, options);
        },
    };

    // Another app of this site changed the language: follow it.
    window.addEventListener("storage", (event) => {
        if ((event.key !== KEY && event.key !== null) || !i18n.data) return;
        const code = i18n.resolve();
        if (code === i18n.lang) return;
        i18n.lang = code;
        i18n.apply();
        document.querySelectorAll("select.language").forEach((select) => (select.value = code));
        listeners.forEach((listener) => listener(code));
    });

    window.i18n = i18n;
})();


/* ============================================================
   popup.js — window.popups: dialogs, sheets, toasts
   ============================================================ */
// Everything that pops up over the page, in every app: the questions and messages (dialogs) and the short notes (toasts).
// An app never uses alert, confirm, or prompt of the browser, and never makes a popup of its own. The look is in assets/css/style.css (.shared-dialog*, .shared-toast*), the same in every app.
//
// A dialog, which waits for an answer:
//   if (await popups.ask({ text: "Delete this chat?", ok: "Delete" })) { ... }       true when the user confirms, false when not
//   const name = await popups.ask({ text: "Chat name:", value: "Old name" });         the text the user typed, or null when cancelled
//   await popups.tell({ text: "Saved." });                                            a message with one button
//   The options are text, title, ok, cancel (the texts of the buttons; they are in the language of the page when not given), value, and kind (the border: info, warning, error, or success; none is the normal border).
//
// A sheet, a panel at an edge of the page (a drawer is a sheet at the bottom); it waits until it is closed:
//   await popups.sheet({ title: "Edit profile", text: "What is in it.", side: "end" });    side: start, end (the default), top, or bottom
//   await popups.sheet({ title: "Filters", node: someElement, side: "bottom" });             a node instead of a text
//
// A command, a search with a list under it; it gives the value of the item that is picked, or null:
//   const value = await popups.command({ items: [{ label: "Open", hint: "Ctrl O", value: "open" }] });
//
// A toast, a short note at the bottom of the page that goes away by itself:
//   popups.toast("Copied.");
//   popups.toast("Failed.", { kind: "error" });                                       the kind gives the colour of the border and the icon
//   const note = popups.toast("Deleting...", { kind: "info", duration: 0 });          stays until it is closed
//   note.set("Still deleting..."); note.close();
//   const bar = popups.toast("Uploading...", { duration: 0, progress: 0 });           with a progress bar (0 to 1)
//   bar.set("Uploading 3 of 9", 0.33); bar.close();
//   The options are kind, duration (milliseconds; 0 stays until closed), and progress.
//   The kinds are the colours with their meaning: success (green, a good thing, the default), info (blue, neutral, the default with progress),
//   warning (yellow, be careful), and error (red, a bad or sensitive thing: a failure, a deletion). An error and a warning stay longer.
//
// The texts of the buttons are in assets/data/popup.js, in every supported language. The page needs assets/js/i18n.js before this script.
(() => {
    const TEXTS = new URL("../data/popup.js", import.meta.url).href;
    const TOAST_TIME = 3500;
    const TOAST_TIME_LONG = 6000;
    let texts = null;
    let element = null;
    let list = null;
    // The element of the body that holds every popup (#popups in the page); a page that has none gets it here.
    const root = () => document.getElementById("popups") ?? document.body.appendChild(Object.assign(document.createElement("div"), { id: "popups", className: "popups" }));

    async function load() {
        texts ??= (await import(TEXTS)).default;
    }

    // A text of popup.js in the language of the page.
    const say = (key) => (window.i18n ? window.i18n.pick(texts[key]) : texts[key]["en-US"]);

    function part(tag, className, parent, hidden = false) {
        const node = document.createElement(tag);
        node.className = className + (hidden ? " hidden" : "");
        parent.appendChild(node);
        return node;
    }

    /* ---------- dialogs ---------- */

    // The dialog is made once, when it is first needed.
    function build() {
        const dialog = document.createElement("dialog");
        dialog.className = "shared-dialog";
        const form = part("form", "shared-dialog-form", dialog);
        form.method = "dialog";
        const parts = {
            dialog,
            form,
            title: part("h2", "shared-dialog-title", form, true),
            text: part("span", "shared-dialog-text", form),
            input: part("input", "shared-dialog-input", form, true),
        };
        parts.input.type = "text";
        const actions = part("div", "shared-dialog-actions", form);
        parts.cancel = part("button", "shared-dialog-cancel", actions);
        parts.cancel.type = "button";
        parts.confirm = part("button", "shared-dialog-confirm primary", actions);
        parts.confirm.type = "submit";
        for (const button of [parts.cancel, parts.confirm]) button.appendChild(document.createElement("span"));
        root().appendChild(dialog);
        return parts;
    }

    async function show({ text = "", title = "", ok, cancel, value = null, single = false, kind = "" }) {
        await load();
        element ??= build();
        const { dialog, form, input } = element;
        // a dialog that is still open (another question at the same time) is closed first
        if (dialog.open) dialog.close();
        dialog.dataset.kind = kind;
        element.title.textContent = title;
        element.title.classList.toggle("hidden", !title);
        element.text.textContent = text;
        element.text.classList.toggle("hidden", !text);
        element.confirm.firstChild.textContent = ok ?? say("ok");
        element.cancel.firstChild.textContent = cancel ?? say("cancel");
        element.cancel.classList.toggle("hidden", single);
        input.classList.toggle("hidden", value === null);
        input.setAttribute("aria-label", text || title);
        if (value !== null) input.value = value;

        return new Promise((resolve) => {
            let answer = value === null ? false : null;
            form.onsubmit = () => {
                answer = value === null ? true : input.value;
            };
            element.cancel.onclick = () => dialog.close();
            dialog.addEventListener("close", () => resolve(answer), { once: true });
            dialog.showModal();
            if (value !== null) {
                input.focus();
                input.select();
            } else element.confirm.focus();
        });
    }

    /* ---------- the sheet and the command ---------- */

    // A dialog that is made for one use and removed when it closes.
    function temporary(className) {
        const dialog = document.createElement("dialog");
        dialog.className = className;
        root().appendChild(dialog);
        // a click on the backdrop closes it
        dialog.addEventListener("click", (event) => { if (event.target === dialog) dialog.close(); });
        return dialog;
    }

    async function sheet({ title = "", text = "", node = null, side = "end" }) {
        await load();
        const dialog = temporary("shared-sheet");
        dialog.dataset.side = side;
        const header = part("div", "shared-sheet-header", dialog);
        part("h2", "shared-sheet-title", header).textContent = title;
        const close = part("button", "shared-sheet-close", header);
        close.type = "button";
        close.textContent = say("close");
        close.addEventListener("click", () => dialog.close());
        const body = part("div", "shared-sheet-body", dialog);
        if (node) body.appendChild(node);
        else body.textContent = text;
        return new Promise((resolve) => {
            dialog.addEventListener("close", () => { dialog.remove(); resolve(); }, { once: true });
            dialog.showModal();
            close.focus();
        });
    }

    async function command({ items = [], placeholder }) {
        await load();
        const dialog = temporary("shared-command");
        const input = part("input", "shared-command-input", dialog);
        input.type = "text";
        input.placeholder = placeholder ?? say("search");
        input.setAttribute("aria-label", input.placeholder);
        const list = part("div", "shared-command-list", dialog);
        let shown = items;
        let active = 0;
        let picked = null;
        const draw = () => {
            list.replaceChildren();
            if (!shown.length) part("span", "shared-command-empty", list).textContent = say("empty");
            shown.forEach((item, index) => {
                const button = part("button", "shared-command-item" + (index === active ? " on" : ""), list);
                button.type = "button";
                part("span", "", button).textContent = item.label;
                if (item.hint) part("span", "shared-command-hint", button).textContent = item.hint;
                button.addEventListener("click", () => { picked = item.value; dialog.close(); });
            });
        };
        input.addEventListener("input", () => {
            const query = input.value.trim().toLowerCase();
            shown = items.filter((item) => item.label.toLowerCase().includes(query));
            active = 0;
            draw();
        });
        input.addEventListener("keydown", (event) => {
            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                event.preventDefault();
                if (shown.length) active = (active + (event.key === "ArrowDown" ? 1 : shown.length - 1)) % shown.length;
                draw();
                list.querySelector(".on")?.scrollIntoView({ block: "nearest" });
            } else if (event.key === "Enter" && shown[active]) {
                event.preventDefault();
                picked = shown[active].value;
                dialog.close();
            }
        });
        draw();
        return new Promise((resolve) => {
            dialog.addEventListener("close", () => { dialog.remove(); resolve(picked); }, { once: true });
            dialog.showModal();
            input.focus();
        });
    }

    /* ---------- toasts ---------- */

    // The list is a popover, so it is in the top layer: a toast shows above an open dialog too.
    function buildList() {
        const node = document.createElement("div");
        node.className = "shared-toasts";
        node.setAttribute("popover", "manual");
        node.setAttribute("role", "status");
        node.setAttribute("aria-live", "polite");
        root().appendChild(node);
        return node;
    }

    function toast(text, { progress = null, kind = progress === null ? "success" : "info", duration = kind === "error" || kind === "warning" ? TOAST_TIME_LONG : TOAST_TIME } = {}) {
        list ??= buildList();
        const note = part("div", `shared-toast ${kind}` + (progress === null ? "" : " with-bar"), list);
        part("span", "shared-toast-icon", note);
        const label = part("span", "shared-toast-text", note);
        label.textContent = text;
        const fill = progress === null ? null : part("i", "shared-toast-fill", part("div", "shared-toast-bar", note));
        let timer = 0;

        const close = () => {
            clearTimeout(timer);
            note.remove();
            if (!list.children.length && list.matches(":popover-open")) list.hidePopover();
        };
        const set = (newText, newProgress) => {
            if (newText !== undefined) label.textContent = newText;
            if (fill && newProgress !== undefined) fill.style.width = Math.round(newProgress * 100) + "%";
        };
        set(undefined, progress ?? 0);

        // shown again each time, so it is above anything opened since the last toast
        if (list.matches(":popover-open")) list.hidePopover();
        list.showPopover();
        if (duration) timer = setTimeout(close, duration);
        return { set, close };
    }

    window.popups = {
        ask: (options = {}) => show(options),
        tell: (options = {}) => show({ ...options, single: true }),
        sheet,
        command,
        toast,
    };
})();


/* ============================================================
   autocomplete.js — window.autocomplete: search suggestions
   ============================================================ */
// Autocomplete for the search inputs of every app: while the user types, a list of suggestions shows under the input.
//   autocomplete.attach(input, { suggestions: () => ["Documents", "Images"] });
// suggestions gives the texts to offer (it is asked each time the user types, so it can follow what the page shows).
// A suggestion that is picked is put in the input, and the input gets an "input" event, so the search runs as if it was typed.
// Keys: arrow down and up move through the list, Enter picks the marked suggestion, Escape closes the list.
// The list is drawn by the page itself (not the datalist of the browser), in the style of the app (see assets/css/style.css).
(() => {
    const MAX = 6;
    let counter = 0;

    function attach(input, { suggestions, max = MAX }) {
        const id = `autocomplete-${++counter}`;
        const list = document.createElement("div");
        list.id = id;
        list.className = "autocomplete-list hidden";
        list.setAttribute("role", "listbox");
        document.body.appendChild(list);

        input.setAttribute("role", "combobox");
        input.setAttribute("aria-autocomplete", "list");
        input.setAttribute("aria-controls", id);
        input.setAttribute("aria-expanded", "false");
        input.autocomplete = "off";

        let options = [];
        let active = -1;

        const close = () => {
            list.classList.add("hidden");
            input.setAttribute("aria-expanded", "false");
            input.removeAttribute("aria-activedescendant");
            active = -1;
        };

        const place = () => {
            const box = input.getBoundingClientRect();
            list.style.width = `${box.width}px`;
            list.style.top = `${box.bottom}px`;
            if (document.documentElement.dir === "rtl") {
                list.style.right = `${document.documentElement.clientWidth - box.right}px`;
                list.style.left = "auto";
            } else {
                list.style.left = `${box.left}px`;
                list.style.right = "auto";
            }
        };

        const mark = (index) => {
            active = index;
            options.forEach((option, i) => {
                option.classList.toggle("active", i === index);
                option.setAttribute("aria-selected", String(i === index));
            });
            if (index >= 0) input.setAttribute("aria-activedescendant", options[index].id);
            else input.removeAttribute("aria-activedescendant");
        };

        const pick = (text) => {
            input.value = text;
            input.dispatchEvent(new Event("input", { bubbles: true }));
            close();
        };

        // The suggestions that fit what is typed: the ones that start with it first, then the ones that hold it.
        const fit = (query) => {
            const lower = query.toLowerCase();
            const seen = new Set();
            const starts = [], holds = [];
            for (const text of suggestions()) {
                const key = String(text).toLowerCase();
                if (!key || seen.has(key) || key === lower) continue;
                seen.add(key);
                if (key.startsWith(lower)) starts.push(String(text));
                else if (key.includes(lower)) holds.push(String(text));
            }
            return [...starts, ...holds].slice(0, max);
        };

        const render = () => {
            const query = input.value.trim();
            const texts = query ? fit(query) : [];
            if (!texts.length) return close();
            list.replaceChildren();
            options = texts.map((text, i) => {
                const option = document.createElement("div");
                option.id = `${id}-${i}`;
                option.className = "autocomplete-option";
                option.setAttribute("role", "option");
                const at = text.toLowerCase().indexOf(query.toLowerCase());
                const match = document.createElement("span");
                match.className = "autocomplete-match";
                match.textContent = text.slice(at, at + query.length);
                option.append(text.slice(0, at), match, text.slice(at + query.length));
                option.addEventListener("mousedown", (event) => {
                    event.preventDefault(); // the input keeps the focus
                    pick(text);
                });
                option.addEventListener("mousemove", () => mark(i));
                list.appendChild(option);
                return option;
            });
            place();
            list.classList.remove("hidden");
            input.setAttribute("aria-expanded", "true");
            mark(-1);
        };

        input.addEventListener("input", render);
        input.addEventListener("focus", render);
        input.addEventListener("blur", close);
        input.addEventListener("keydown", (event) => {
            if (list.classList.contains("hidden")) return;
            if (event.key === "ArrowDown") {
                event.preventDefault();
                mark((active + 1) % options.length);
            } else if (event.key === "ArrowUp") {
                event.preventDefault();
                mark(active <= 0 ? options.length - 1 : active - 1);
            } else if (event.key === "Enter" && active >= 0) {
                event.preventDefault();
                pick(options[active].textContent);
            } else if (event.key === "Escape") {
                event.stopPropagation();
                close();
            }
        });
        window.addEventListener("resize", () => !list.classList.contains("hidden") && place());
        window.addEventListener("scroll", close, true);
    }

    window.autocomplete = { attach };
})();


/* ============================================================
   components.js — window.components: shared UI helpers & kit-* tags
   ============================================================ */
// The small helpers that every app wrote again, made once. They go with the templates of style.css; Kitmu shows each of them.
//   components.element("div", "card", "Text")                  an element with a class and a text
//   components.icon("trash")                                   <span class="icon icon-trash"></span>
//   components.formatSize(1536000)                             "1.5 MB", with the numbers of the language of the page
//   components.extensionOf("Image.PNG")                        "png" (an empty text when there is no dot)
//   const say = components.status(document.getElementById("status"));
//   say("Choose a file.");                                     the hint line of the footer (a notice is a popup: popups.toast)
//   const menu = components.drawer({ sidebar, button });       the sidebar that opens over the main on a narrow screen
//   menu.set(true);                                            opens it (Escape closes it and gives the focus back to the button)
//   components.download("notes.txt", "Hello", "text/plain");   saves a text or a Blob as a file
//   components.expand({ toggle, body, open: false });          a button that opens and closes its body (the expandable part of the template)
//   components.menu({ anchor, items });                         a menu under a button (items: { label, icon, danger, onSelect } or { separator: true });
//                                                               onSelect that gives false keeps it open; { point: { x, y } } instead of anchor is a context menu
//   components.select({ trigger, options, value, onChange });   a button that shows the value and opens a menu of the options
//   components.otp({ length, onComplete });                     one input for each character of a code (its element is .element)
//   components.resizable(container);                            the handle between two panels moves with the pointer and the arrows
//   components.carousel(root);                                  the buttons data-carousel="previous" and "next" move the track
//   components.calendar({ selected, onSelect });                a month of days (its element is .element)
//   components.chart({ type: "bar" or "line", data });          an svg; data is [{ label, value }]
//   components.dataTable({ columns, rows, pageSize, labels });  a table with a filter, a sort on each column, and pages
//   components.scroller(container);                             follow() keeps the end in view only while the reader is at the end
//   components.questionnaire({ items, labels, onSubmit });      questions one after another, with choices
//   <kit-alert kind="error" heading="Failed">The text.</kit-alert>   a component with several parts is one tag: kit-alert, kit-card, kit-item, kit-empty, kit-attachment, kit-message.
//                                                               It builds its parts, so a change of the component reaches every app; the attributes are properties too (element.heading = "...").
//   components.make("alert", { kind: "error", heading: "Failed" }, ["The text."])   the same from a script
//   The parts of the page are tags too: <kit-header theme menu>, <kit-sidebar>, <kit-footer status>; and kit-collapsible, kit-breadcrumbs, kit-tabs, kit-pagination,
//   kit-trace-line, kit-marker, kit-field, kit-search. Their texts that are the same in every app (the account button, the copyright) are in assets/data/kit.js.
//   components.closeOverlay();                                  closes the menu or the popover that is open
//   components.popover({ anchor, content });                    a panel with anything in it, under a button; both close on Escape, on a click outside, on a scroll
(() => {
    const KIT_TEXTS = new URL("../data/kit.js", import.meta.url).href;
    function element(tag, className, text) {
        const node = document.createElement(tag);
        if (className) node.className = className;
        if (text != null) node.textContent = text;
        return node;
    }

    const icon = (name) => element("span", `icon icon-${name}`);

    const extensionOf = (name) => (name.includes(".") ? name.split(".").pop().toLowerCase() : "");

    function formatSize(bytes) {
        const number = (value) => (window.i18n ? window.i18n.number(value, { maximumFractionDigits: value < 10 ? 1 : 0 }) : value.toFixed(value < 10 ? 1 : 0));
        if (bytes < 1024) return `${bytes} B`;
        const units = ["KB", "MB", "GB", "TB"];
        let value = bytes;
        let index = -1;
        do {
            value /= 1024;
            index++;
        } while (value >= 1024 && index < units.length - 1);
        return `${number(value)} ${units[index]}`;
    }

    // The function that writes in the hint line of the footer: say(text). It is for what the page tells about itself (what to do first, how many items there are);
    // a notice (work that goes on, a result, an error) is a popup, popups.toast in assets/js/popup.js.
    function status(node) {
        return (text) => { node.textContent = text; };
    }

    // The sidebar that is hidden on a narrow screen and opened over the main by the menu button.
    function drawer({ sidebar, button, focus = ".sidebar-item.on, .sidebar-item:not(:disabled)" }) {
        const set = (open) => {
            sidebar.classList.toggle("open", open);
            button.setAttribute("aria-expanded", String(open));
            if (open) sidebar.querySelector(focus)?.focus();
        };
        button.addEventListener("click", () => set(!sidebar.classList.contains("open")));
        document.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && sidebar.classList.contains("open") && button.offsetParent) {
                event.stopImmediatePropagation();
                set(false);
                button.focus();
            }
        });
        return { set };
    }

    function download(name, content, type = "application/octet-stream") {
        const link = document.createElement("a");
        link.href = URL.createObjectURL(content instanceof Blob ? content : new Blob([content], { type }));
        link.download = name;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(link.href), 10000);
    }

    // The button opens and closes its body; aria-expanded follows (the template shows it as a green or a red line).
    function expand({ toggle, body, open = true }) {
        const set = (value) => {
            body.hidden = !value;
            toggle.setAttribute("aria-expanded", String(value));
        };
        toggle.addEventListener("click", () => set(body.hidden));
        set(open);
        return { set };
    }

    /* ---------- the menu and the popover: one is open at a time, under the button that opened it ---------- */
    let open = null;

    const closeOpen = () => open?.close();

    // Puts the panel under the anchor (above it when there is no room), or at a point, and inside the window.
    function place(node, { anchor, point, align }) {
        const margin = 8;
        const gap = 6;
        const rtl = getComputedStyle(document.documentElement).direction === "rtl";
        let left;
        let top;
        if (point) {
            left = point.x;
            top = point.y;
        } else {
            const box = anchor.getBoundingClientRect();
            const atEnd = (align === "end") !== rtl;
            left = atEnd ? box.right - node.offsetWidth : box.left;
            top = box.bottom + gap;
            if (top + node.offsetHeight > window.innerHeight - margin) top = box.top - node.offsetHeight - gap;
        }
        node.style.left = `${Math.max(margin, Math.min(left, window.innerWidth - node.offsetWidth - margin))}px`;
        node.style.top = `${Math.max(margin, Math.min(top, window.innerHeight - node.offsetHeight - margin))}px`;
    }

    function show(node, { anchor, point, align = "start" }) {
        // a second click on the same button closes what it opened
        const again = open && anchor && open.anchor === anchor;
        closeOpen();
        if (again) return null;
        (document.getElementById("popups") ?? document.body).appendChild(node);
        place(node, { anchor, point, align });
        const outside = (event) => { if (!node.contains(event.target) && !anchor?.contains(event.target)) close(); };
        const escape = (event) => {
            if (event.key !== "Escape") return;
            event.stopPropagation();
            close(true);
        };
        const scrolled = (event) => { if (!node.contains(event.target)) close(); };   // the page scrolls: it closes; the list inside it scrolls: it stays
        const close = (refocus = false) => {
            if (open?.node !== node) return;
            node.remove();
            document.removeEventListener("pointerdown", outside, true);
            document.removeEventListener("keydown", escape, true);
            window.removeEventListener("resize", close);
            document.removeEventListener("scroll", scrolled, true);
            open = null;
            if (refocus) anchor?.focus();
        };
        open = { node, anchor, close };
        document.addEventListener("pointerdown", outside, true);
        document.addEventListener("keydown", escape, true);
        window.addEventListener("resize", close);
        document.addEventListener("scroll", scrolled, true);
        return { node, close };
    }

    function menu({ anchor, point, items, align, scroll = false }) {
        const node = element("div", "menu");
        node.setAttribute("role", "menu");
        if (scroll) {   // a long list scrolls inside the menu
            node.style.maxHeight = "min(32rem, 60vh)";
            node.style.overflowY = "auto";
        }
        const buttons = [];
        let handle = null;
        for (const entry of items) {
            if (entry.separator) {
                node.appendChild(element("hr", "menu-separator"));
                continue;
            }
            const button = element("button", `menu-item${entry.danger ? " danger" : ""}`);
            button.type = "button";
            button.setAttribute("role", "menuitem");
            button.disabled = !!entry.disabled;
            if (entry.icon) button.appendChild(icon(entry.icon));
            button.appendChild(element("span", "", entry.label));
            button.addEventListener("click", () => {
                const keep = entry.onSelect?.({ button, close: () => handle.close(true) }) === false;
                if (!keep) handle.close(true);
            });
            buttons.push(button);
            node.appendChild(button);
        }
        handle = show(node, { anchor, point, align });
        if (!handle) return null;
        // Keyboard in the menu: arrows move, Home and End go to the ends, Escape closes and gives the focus back, Tab leaves.
        node.addEventListener("keydown", (event) => {
            const enabled = buttons.filter((button) => !button.disabled);
            const index = enabled.indexOf(document.activeElement);
            if (event.key === "ArrowDown") {
                event.preventDefault();
                enabled[(index + 1) % enabled.length].focus();
            } else if (event.key === "ArrowUp") {
                event.preventDefault();
                enabled[(index - 1 + enabled.length) % enabled.length].focus();
            } else if (event.key === "Home") {
                event.preventDefault();
                enabled[0].focus();
            } else if (event.key === "End") {
                event.preventDefault();
                enabled[enabled.length - 1].focus();
            } else if (event.key === "Tab") handle.close();
        });
        buttons.find((button) => !button.disabled)?.focus();
        return handle;
    }

    function popover({ anchor, content, align }) {
        const node = element("div", "popover");
        node.tabIndex = -1;
        node.append(content);
        const handle = show(node, { anchor, align });
        if (!handle) return null;
        (node.querySelector("button, input, select, textarea, a[href]") ?? node).focus();
        return handle;
    }

    /* ---------- the select: a button that shows the value and opens a menu of the options ---------- */
    function select({ trigger, options, value, onChange }) {
        const label = element("span");
        trigger.classList.add("select-trigger");
        trigger.replaceChildren(label, icon("chevron-down"));
        let current = value ?? options[0]?.value;
        const refresh = () => {
            label.textContent = options.find((option) => option.value === current)?.label ?? "";
        };
        refresh();
        trigger.addEventListener("click", () => {
            const handle = menu({
                anchor: trigger,
                items: options.map((option) => ({
                    label: option.label,
                    icon: option.value === current ? "check" : "blank",
                    onSelect: () => {
                        current = option.value;
                        refresh();
                        onChange?.(current);
                    },
                })),
            });
            if (handle) handle.node.style.minWidth = `${trigger.offsetWidth}px`;
        });
        return {
            get value() {
                return current;
            },
            set(next) {
                current = next;
                refresh();
            },
        };
    }

    /* ---------- the tag <select>: it opens the menu of the kit, not the list of the browser ---------- */
    // The select keeps its value, its options, and its change event, so an app changes nothing; only the list that opens is the menu of the kit (a second click, Escape, and the arrows work as in every menu).
    // Every <select> of a page gets it (the ones that are made later too); data-native keeps the list of the browser.
    function enhanceSelect(native) {
        if (native.dataset.kitSelect !== undefined || native.hasAttribute("data-native")) return;
        native.dataset.kitSelect = "";
        const choose = () => {
            if (native.disabled) return;
            const handle = menu({
                anchor: native,
                scroll: true,
                items: [...native.options].filter((option) => !option.hidden).map((option) => ({
                    label: option.textContent,
                    icon: option.selected ? "check" : "blank",
                    disabled: option.disabled,
                    onSelect: () => {
                        if (native.value === option.value) return;
                        native.value = option.value;
                        native.dispatchEvent(new Event("input", { bubbles: true }));
                        native.dispatchEvent(new Event("change", { bubbles: true }));
                    },
                })),
            });
            if (!handle) return;
            handle.node.style.minWidth = `${native.offsetWidth}px`;
            const picked = [...handle.node.querySelectorAll(".menu-item")].find((button) => button.querySelector(".icon-check"));
            if (picked) { picked.focus(); picked.scrollIntoView({ block: "nearest" }); }
        };
        native.addEventListener("mousedown", (event) => {
            if (event.button !== 0) return;
            event.preventDefault();   // the list of the browser does not open
            native.focus();
            choose();
        });
        native.addEventListener("keydown", (event) => {
            if (![" ", "Enter", "ArrowDown", "ArrowUp"].includes(event.key)) return;
            event.preventDefault();
            choose();
        });
    }
    // The slider keeps --position (0 to 1) of its knob, for the CSS of assets/css/style.css that paints the track up to it. An app sets the value (and the end) from its code,
    // which does not fire "input": the value of the element is watched, and so are min and max.
    const placeSlider = (input) => {
        const min = Number(input.min || 0);
        const max = Number(input.max || 100);
        input.style.setProperty("--position", max > min ? String(Math.min(1, Math.max(0, (Number(input.value) - min) / (max - min)))) : "0");
    };
    function enhanceSlider(input) {
        if (input.dataset.kitSlider !== undefined) return;
        input.dataset.kitSlider = "";
        const own = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value");
        Object.defineProperty(input, "value", { configurable: true, get() { return own.get.call(this); }, set(next) { own.set.call(this, next); placeSlider(this); } });
        input.addEventListener("input", () => placeSlider(input));
        new MutationObserver(() => placeSlider(input)).observe(input, { attributes: true, attributeFilter: ["min", "max", "value", "step"] });
        placeSlider(input);
    }
    const enhanceSelects = (root) => {
        if (root.matches?.("select")) enhanceSelect(root);
        root.querySelectorAll?.("select").forEach(enhanceSelect);
        if (root.matches?.("input.slider")) enhanceSlider(root);
        root.querySelectorAll?.("input.slider").forEach(enhanceSlider);
    };
    enhanceSelects(document);
    new MutationObserver((records) => records.forEach((record) => record.addedNodes.forEach((node) => node.nodeType === 1 && enhanceSelects(node)))).observe(document.documentElement, { childList: true, subtree: true });

    /* ---------- the one time code: one input for each character ---------- */
    function otp({ length = 6, onComplete }) {
        const box = element("div", "otp");
        const inputs = [];
        const value = () => inputs.map((input) => input.value).join("");
        const check = () => {
            if (value().length === length) onComplete?.(value());
        };
        for (let index = 0; index < length; index++) {
            const input = element("input");
            input.type = "text";
            input.inputMode = "numeric";
            input.maxLength = 1;
            input.autocomplete = "one-time-code";
            input.setAttribute("aria-label", String(index + 1));
            input.addEventListener("input", () => {
                input.value = input.value.replace(/\D/g, "").slice(-1);
                if (input.value) inputs[index + 1]?.focus();
                check();
            });
            input.addEventListener("keydown", (event) => {
                if (event.key === "Backspace" && !input.value) inputs[index - 1]?.focus();
            });
            input.addEventListener("paste", (event) => {
                event.preventDefault();
                const digits = (event.clipboardData?.getData("text") ?? "").replace(/\D/g, "").slice(0, length - index);
                [...digits].forEach((digit, offset) => { inputs[index + offset].value = digit; });
                inputs[Math.min(index + digits.length, length - 1)].focus();
                check();
            });
            inputs.push(input);
            box.appendChild(input);
        }
        return {
            element: box,
            get value() {
                return value();
            },
            clear() {
                inputs.forEach((input) => { input.value = ""; });
                inputs[0].focus();
            },
        };
    }

    /* ---------- resizable panels: the handle moves with the pointer and with the arrows ---------- */
    function resizable(container) {
        const handle = container.querySelector(".resizable-handle");
        const first = handle.previousElementSibling;
        const vertical = container.classList.contains("vertical");
        handle.tabIndex = 0;
        handle.setAttribute("role", "separator");
        handle.setAttribute("aria-orientation", vertical ? "horizontal" : "vertical");
        const set = (pixels) => {
            const total = (vertical ? container.clientHeight : container.clientWidth) - (vertical ? handle.offsetHeight : handle.offsetWidth);
            const size = Math.max(total * 0.1, Math.min(pixels, total * 0.9));
            first.style.flex = `none`;
            first.style[vertical ? "height" : "width"] = `${size}px`;
        };
        handle.addEventListener("pointerdown", (event) => {
            handle.setPointerCapture(event.pointerId);
            const move = (moveEvent) => {
                const box = container.getBoundingClientRect();
                const rtl = getComputedStyle(container).direction === "rtl";
                set(vertical ? moveEvent.clientY - box.top : rtl ? box.right - moveEvent.clientX : moveEvent.clientX - box.left);
            };
            const stop = () => {
                handle.removeEventListener("pointermove", move);
                handle.removeEventListener("pointerup", stop);
            };
            handle.addEventListener("pointermove", move);
            handle.addEventListener("pointerup", stop);
        });
        handle.addEventListener("keydown", (event) => {
            const step = event.key === "ArrowRight" || event.key === "ArrowDown" ? 16 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -16 : 0;
            if (!step) return;
            event.preventDefault();
            const rtl = getComputedStyle(container).direction === "rtl" && !vertical;
            set((vertical ? first.offsetHeight : first.offsetWidth) + (rtl ? -step : step));
        });
        return { set };
    }

    /* ---------- the carousel: the buttons move the track by one width ---------- */
    function carousel(root) {
        const track = root.querySelector(".carousel-track");
        const sign = getComputedStyle(root).direction === "rtl" ? -1 : 1;
        const go = (direction) => track.scrollBy({ left: direction * sign * track.clientWidth, behavior: "smooth" });
        root.querySelector('[data-carousel="previous"]').addEventListener("click", () => go(-1));
        root.querySelector('[data-carousel="next"]').addEventListener("click", () => go(1));
    }

    /* ---------- the calendar: a month, in the language of the page; a day is picked with a click ---------- */
    function calendar({ value = new Date(), selected = null, onSelect }) {
        const language = window.i18n?.lang ?? navigator.language;
        let view = new Date(value.getFullYear(), value.getMonth(), 1);
        let picked = selected;
        const locale = new Intl.Locale(language);
        const firstDay = ((locale.getWeekInfo?.() ?? locale.weekInfo)?.firstDay ?? 7) % 7;   // 0 is Sunday
        const number = new Intl.NumberFormat(language);
        const box = element("div", "calendar");
        const header = element("div", "calendar-header");
        const previous = element("button", "square");
        const title = element("span", "calendar-title");
        const next = element("button", "square");
        previous.type = next.type = "button";
        previous.append(icon("chevron-left"));
        next.append(icon("chevron-right"));
        previous.setAttribute("aria-label", "-");
        next.setAttribute("aria-label", "+");
        header.append(previous, title, next);
        const grid = element("div", "calendar-grid");
        box.append(header, grid);
        const same = (a, b) => a && b && a.toDateString() === b.toDateString();
        const draw = () => {
            title.textContent = new Intl.DateTimeFormat(language, { month: "long", year: "numeric" }).format(view);
            grid.replaceChildren();
            const names = new Intl.DateTimeFormat(language, { weekday: "short" });
            for (let day = 0; day < 7; day++) grid.append(element("span", "calendar-weekday", names.format(new Date(2024, 0, 7 + ((firstDay + day) % 7)))));
            const start = new Date(view.getFullYear(), view.getMonth(), 1 - ((view.getDay() - firstDay + 7) % 7));
            for (let index = 0; index < 42; index++) {
                const date = new Date(start.getFullYear(), start.getMonth(), start.getDate() + index);
                const button = element("button", "calendar-day", number.format(date.getDate()));
                button.type = "button";
                button.classList.toggle("outside", date.getMonth() !== view.getMonth());
                button.classList.toggle("today", same(date, new Date()));
                button.classList.toggle("on", same(date, picked));
                button.addEventListener("click", () => {
                    picked = date;
                    if (date.getMonth() !== view.getMonth()) view = new Date(date.getFullYear(), date.getMonth(), 1);
                    draw();
                    onSelect?.(date);
                });
                grid.append(button);
            }
        };
        previous.addEventListener("click", () => { view = new Date(view.getFullYear(), view.getMonth() - 1, 1); draw(); });
        next.addEventListener("click", () => { view = new Date(view.getFullYear(), view.getMonth() + 1, 1); draw(); });
        draw();
        return {
            element: box,
            get value() {
                return picked;
            },
        };
    }

    /* ---------- the chart: bars or a line, in svg ---------- */
    function chart({ type = "bar", data, width = 320, height = 160 }) {
        const namespace = "http://www.w3.org/2000/svg";
        const make = (tag, attributes, className) => {
            const node = document.createElementNS(namespace, tag);
            for (const [name, text] of Object.entries(attributes)) node.setAttribute(name, text);
            if (className) node.setAttribute("class", className);
            return node;
        };
        const svg = make("svg", { viewBox: `0 0 ${width} ${height}`, role: "img" }, "chart");
        const left = 8;
        const bottom = 22;
        const top = 8;
        const plotWidth = width - left * 2;
        const plotHeight = height - top - bottom;
        const maximum = Math.max(...data.map((point) => point.value), 1);
        const slot = plotWidth / data.length;
        svg.append(make("line", { x1: left, y1: top + plotHeight, x2: width - left, y2: top + plotHeight }, "chart-axis"));
        const points = data.map((point, index) => {
            const x = left + slot * index + slot / 2;
            const y = top + plotHeight - (point.value / maximum) * plotHeight;
            const label = make("text", { x, y: height - 6 }, "chart-label");
            label.textContent = point.label;
            svg.append(label);
            if (type === "bar") svg.append(make("rect", { x: x - slot * 0.3, y, width: slot * 0.6, height: top + plotHeight - y, rx: 2 }, "chart-bar"));
            return [x, y];
        });
        if (type === "line") {
            svg.append(make("polyline", { points: points.map((point) => point.join(",")).join(" ") }, "chart-line"));
            points.forEach(([x, y]) => svg.append(make("circle", { cx: x, cy: y, r: 3 }, "chart-dot")));
        }
        return svg;
    }

    /* ---------- the data table: a filter, a sort on each column, and pages ---------- */
    function dataTable({ columns, rows, pageSize = 5, labels = {} }) {
        const text = { filter: "Filter...", previous: "Previous", next: "Next", empty: "No results.", ...labels };
        const state = { query: "", key: null, direction: "ascending", page: 0 };
        const box = element("div", "data-table");
        const search = element("label", "searchbox");
        const input = element("input");
        input.type = "search";
        input.placeholder = text.filter;
        input.setAttribute("aria-label", text.filter);
        search.append(icon("search"), input);
        const table = element("table", "table");
        const footer = element("div", "data-table-footer");
        const count = element("span");
        const pages = element("div", "pagination");
        const previous = element("button", "", text.previous);
        const following = element("button", "", text.next);
        previous.type = following.type = "button";
        pages.append(previous, following);
        footer.append(count, pages);
        const scroll = element("div", "scroll-area");   // a table that is wider than the screen scrolls inside its own box
        scroll.append(table);
        box.append(search, scroll, footer);
        const draw = () => {
            const query = state.query.toLowerCase();
            let shown = rows.filter((row) => columns.some((column) => String(row[column.key]).toLowerCase().includes(query)));
            if (state.key) {
                const sign = state.direction === "ascending" ? 1 : -1;
                shown = [...shown].sort((a, b) => sign * String(a[state.key]).localeCompare(String(b[state.key]), undefined, { numeric: true }));
            }
            const last = Math.max(0, Math.ceil(shown.length / pageSize) - 1);
            state.page = Math.min(state.page, last);
            const head = element("thead");
            const headRow = element("tr");
            for (const column of columns) {
                const cell = element("th");
                const sort = element("button", "table-sort");
                sort.type = "button";
                sort.append(element("span", "", column.label), icon("arrow-down"));
                if (state.key === column.key) sort.dataset.sort = state.direction;
                cell.setAttribute("aria-sort", state.key === column.key ? state.direction : "none");
                sort.addEventListener("click", () => {
                    state.direction = state.key === column.key && state.direction === "ascending" ? "descending" : "ascending";
                    state.key = column.key;
                    draw();
                });
                cell.append(sort);
                headRow.append(cell);
            }
            head.append(headRow);
            const body = element("tbody");
            const page = shown.slice(state.page * pageSize, state.page * pageSize + pageSize);
            if (!page.length) {
                const cell = element("td", "", text.empty);
                cell.colSpan = columns.length;
                const empty = element("tr");
                empty.append(cell);
                body.append(empty);
            }
            for (const row of page) {
                const line = element("tr");
                for (const column of columns) line.append(element("td", "", String(row[column.key])));
                body.append(line);
            }
            table.replaceChildren(head, body);
            count.textContent = `${shown.length ? state.page * pageSize + 1 : 0}–${state.page * pageSize + page.length} / ${shown.length}`;
            previous.disabled = state.page === 0;
            following.disabled = state.page >= last;
        };
        input.addEventListener("input", () => { state.query = input.value; state.page = 0; draw(); });
        previous.addEventListener("click", () => { state.page--; draw(); });
        following.addEventListener("click", () => { state.page++; draw(); });
        draw();
        return { element: box };
    }

    /* ---------- the message scroller: follows a stream only while the reader is at the end ---------- */
    function scroller(container) {
        let following = true;
        const atEnd = () => container.scrollHeight - container.scrollTop - container.clientHeight < 8;
        container.addEventListener("scroll", () => { following = atEnd(); });
        return {
            follow() {
                if (following) container.scrollTop = container.scrollHeight;
            },
            toEnd() {
                following = true;
                container.scrollTop = container.scrollHeight;
            },
            get following() {
                return following;
            },
        };
    }

    /* ---------- the questionnaire: questions one after another, with choices ---------- */
    function questionnaire({ items, labels = {}, onSubmit }) {
        const text = { previous: "Previous", next: "Next", skip: "Skip", submit: "Submit", required: "Choose an answer.", other: "Another answer", progress: "Question {n} of {total}", ...labels };
        const answers = {};
        let index = 0;
        const box = element("div", "questionnaire");
        const draw = () => {
            const item = items[index];
            const progress = element("span", "questionnaire-progress", text.progress.replace("{n}", index + 1).replace("{total}", items.length));
            const title = element("span", "questionnaire-title", item.prompt);
            const description = element("span", "questionnaire-description", item.description ?? "");
            const list = element("div", "choices");
            const error = element("span", "error");
            const choose = (value) => {
                if (item.multiple) {
                    const chosen = new Set(answers[item.name] ?? []);
                    chosen.has(value) ? chosen.delete(value) : chosen.add(value);
                    answers[item.name] = [...chosen];
                } else answers[item.name] = value;
                draw();
            };
            item.choices.forEach((choice, position) => {
                const button = element("button", "choice");
                button.type = "button";
                const wording = element("span", "choice-text", choice.label);
                if (choice.description) wording.append(element("span", "choice-description", choice.description));
                button.append(element("span", "choice-key", String.fromCharCode(65 + position)), wording);
                const answer = answers[item.name];
                button.classList.toggle("on", item.multiple ? (answer ?? []).includes(choice.value) : answer === choice.value);
                button.addEventListener("click", () => choose(choice.value));
                list.append(button);
            });
            const parts = [progress, title, description, list];
            if (item.input) {
                const field = element("input");
                field.type = "text";
                field.placeholder = item.input.placeholder ?? text.other;
                field.setAttribute("aria-label", item.input.label ?? text.other);
                field.value = item.choices.some((choice) => choice.value === answers[item.name]) ? "" : (answers[item.name] ?? "");
                field.addEventListener("input", () => { answers[item.name] = field.value; });
                parts.push(field);
            }
            const actions = element("div", "questionnaire-actions");
            const last = index === items.length - 1;
            const previous = element("button", "ghost", text.previous);
            previous.type = "button";
            previous.disabled = index === 0;
            previous.addEventListener("click", () => { index--; draw(); });
            const skip = element("button", "ghost", text.skip);
            skip.type = "button";
            skip.addEventListener("click", () => { delete answers[item.name]; if (last) onSubmit?.(answers); else { index++; draw(); } });
            const forward = element("button", "primary", last ? text.submit : text.next);
            forward.type = "button";
            forward.addEventListener("click", () => {
                const answer = answers[item.name];
                if (item.required && (answer === undefined || answer === "" || (Array.isArray(answer) && !answer.length))) {
                    error.textContent = text.required;
                    return;
                }
                if (last) onSubmit?.(answers);
                else { index++; draw(); }
            });
            actions.append(previous);
            if (!item.required) actions.append(skip);
            actions.append(forward);
            parts.push(error, actions);
            box.replaceChildren(...parts);
        };
        draw();
        return { element: box, answers };
    }

    /* ---------- the elements kit-*: one tag builds a component that has several parts, so a change of the component reaches every app ---------- */
    const KIND_ICON = { success: "check", info: "info", warning: "warning", error: "alert" };

    // The texts of the parts that the page parts have on their own (the account button, the copyright): assets/data/kit.js, in every language.
    let kitTexts = null;
    const kitText = (key) => (kitTexts?.[key] ? (window.i18n?.lang ? window.i18n.pick(kitTexts[key]) : kitTexts[key]["en-US"]) : "");
    const withTexts = new Set();   // the tags that show a text of kit.js: they are made again when the language changes
    let refreshing = false;
    function refreshTexts() {
        refreshing = true;
        for (const host of withTexts) host.render();
        refreshing = false;
    }
    import(KIT_TEXTS).then((module) => { kitTexts = module.default; refreshTexts(); }).catch(() => {});

    // The tag keeps what is written inside it (the content, and the nodes with a slot attribute), and builds the parts around it.
    // The attributes of the tag are also properties: element.heading = "Title" sets the attribute, and the parts follow.
    // An attribute can be translated like a text: data-i18n-heading="key" gives heading the text of the key in the language of the page.
    // live: the children are looked at again each time they change (the tag keeps the ones that this function says yes to); texts: the tag shows a text of kit.js.
    function defineElement(name, attributes, build, { live = null, texts = false } = {}) {
        class Kit extends HTMLElement {
            static get observedAttributes() {
                return attributes;
            }

            connectedCallback() {
                if (!this.rendered) this.render();
                if (texts) withTexts.add(this);
            }

            disconnectedCallback() {
                withTexts.delete(this);
            }

            attributeChangedCallback() {
                if (this.rendered && !this.updating) this.render();
            }

            render() {
                this.updating = true;
                this.observer?.disconnect();
                for (const attribute of attributes) {
                    const key = this.getAttribute(`data-i18n-${attribute}`);
                    if (key !== null && window.i18n?.data) this.setAttribute(attribute, window.i18n.t(key));
                }
                if (live) this.original = [...this.childNodes].filter(live);
                else if (!this.rendered) this.original = [...this.childNodes];
                this.rendered = true;
                const slots = {};
                const content = [];
                for (const node of this.original) {
                    const slot = node.nodeType === 1 ? node.getAttribute("slot") : null;
                    if (slot) (slots[slot] ??= []).push(node);
                    else content.push(node);
                }
                const classes = build(this, { content, slots, refresh: refreshing }).filter(Boolean);
                this.classList.remove(...(this.managed ?? []));
                this.classList.add(...classes);
                this.managed = classes;
                if (!refreshing && window.i18n?.data) window.i18n.apply(this);
                if (live && this.isConnected) {
                    this.observer ??= new MutationObserver(() => { if (!this.updating) this.render(); });
                    this.observer.observe(this, { childList: true });
                }
                this.updating = false;
            }
        }
        for (const attribute of attributes) {
            Object.defineProperty(Kit.prototype, attribute, {
                get() {
                    return this.getAttribute(attribute) ?? "";
                },
                set(value) {
                    if (value === false || value == null) this.removeAttribute(attribute);
                    else this.setAttribute(attribute, value === true ? "" : value);
                },
            });
        }
        customElements.define(`kit-${name}`, Kit);
    }

    const hasContent = (nodes) => nodes.some((node) => node.nodeType === 1 || node.textContent.trim());
    const attributeOf = (host, name) => host.getAttribute(name) ?? "";
    let counter = 0;

    defineElement("alert", ["kind", "heading"], (host, { content }) => {
        const kind = host.getAttribute("kind") || "info";
        host.setAttribute("role", "alert");
        const body = element("div", "alert-body");
        if (host.getAttribute("heading")) body.append(element("span", "alert-title", host.getAttribute("heading")));
        const text = element("span", "alert-text");
        text.append(...content);
        body.append(text);
        host.replaceChildren(icon(KIND_ICON[kind] ?? "info"), body);
        return ["alert", kind];
    });

    defineElement("card", ["heading", "description"], (host, { content, slots }) => {
        const parts = [];
        if (host.getAttribute("heading") || host.getAttribute("description")) {
            const header = element("div", "card-header");
            if (host.getAttribute("heading")) header.append(element("span", "card-title", host.getAttribute("heading")));
            if (host.getAttribute("description")) header.append(element("span", "card-description", host.getAttribute("description")));
            parts.push(header);
        }
        if (hasContent(content)) {
            const body = element("div", "card-content");
            body.append(...content);
            parts.push(body);
        }
        if (slots.footer) {
            const footer = element("div", "card-footer");
            footer.append(...slots.footer);
            parts.push(footer);
        }
        host.replaceChildren(...parts);
        return ["card"];
    });

    defineElement("item", ["heading", "description"], (host, { content, slots }) => {
        const body = element("div", "item-body");
        if (host.getAttribute("heading")) body.append(element("span", "item-title", host.getAttribute("heading")));
        if (host.getAttribute("description")) body.append(element("span", "item-description", host.getAttribute("description")));
        if (hasContent(content)) body.append(...content);
        host.replaceChildren(...(slots.media ?? []), body, ...(slots.actions ?? []));
        return ["item"];
    });

    defineElement("empty", ["icon", "heading", "text"], (host, { content, slots }) => {
        const illustration = element("div", "empty-illustration");
        illustration.append(icon(host.getAttribute("icon") || "folder"));
        const text = element("span", "empty-text", host.getAttribute("text") ?? "");
        if (!text.textContent && hasContent(content)) text.append(...content);
        host.replaceChildren(illustration, element("span", "empty-title", host.getAttribute("heading") ?? ""), text, ...(slots.action ?? []));
        return ["empty-state"];
    });

    defineElement("attachment", ["name", "detail", "icon", "image", "kind"], (host, { slots }) => {
        const media = element("span", "attachment-media");
        if (host.getAttribute("image")) media.style.backgroundImage = `url("${host.getAttribute("image")}")`;
        else media.append(icon(host.getAttribute("icon") || "file"));
        const body = element("div", "attachment-content");
        body.append(element("span", "attachment-title", host.getAttribute("name") ?? ""), element("span", "attachment-description", host.getAttribute("detail") ?? ""));
        const parts = [media, body];
        if (slots.actions) {
            const actions = element("div", "attachment-actions");
            actions.append(...slots.actions);
            parts.push(actions);
        }
        host.replaceChildren(...parts);
        return ["attachment", host.getAttribute("kind") === "error" ? "error" : null];
    });

    defineElement("message", ["end", "heading", "footer", "avatar", "bubble"], (host, { content, slots }) => {
        const parts = [];
        if (host.hasAttribute("avatar")) {
            const avatar = element("span", "message-avatar");
            avatar.append(element("span", "avatar", host.getAttribute("avatar")));
            parts.push(avatar);
        }
        const column = element("div", "message-content");
        if (host.getAttribute("heading")) column.append(element("div", "message-header", host.getAttribute("heading")));
        const bubble = element("div", `bubble${host.getAttribute("bubble") ? ` ${host.getAttribute("bubble")}` : ""}`);
        bubble.append(...content);
        column.append(bubble);
        if (slots.footer) {
            for (const node of slots.footer) {
                node.classList.add("message-footer");
                column.append(node);
            }
        } else if (host.getAttribute("footer")) column.append(element("div", "message-footer", host.getAttribute("footer")));
        host.parts = { bubble };
        host.replaceChildren(...parts, column);
        return ["message", host.hasAttribute("end") ? "end" : null];
    });

    /* the parts of the page: the header, the sidebar, and the footer */
    defineElement("header", ["theme", "menu", "menu-label", "menu-text", "no-account", "name"], (host, { refresh }) => {
        // a new language only changes the texts: the buttons stay, because the app has tied its scripts to them
        if (refresh && host.querySelector(".header-tools")) {
            const names = { "theme-button": "theme", "account-button": "account", "menu-button": "menu" };
            for (const button of host.querySelectorAll(".header-tools button")) {
                const label = button.id === "menu-button" ? host.getAttribute("menu-label") || kitText("menu") : kitText(names[button.id]);
                button.setAttribute("aria-label", label);
                if (button.querySelector("span:not(.icon)")) button.querySelector("span:not(.icon)").textContent = label;
                else button.title = label;
            }
            return host.managed;
        }
        const logo = element("div", "logo");
        const name = element("span", "logo-name");
        if (host.getAttribute("name")) name.innerHTML = host.getAttribute("name");
        else name.setAttribute("data-i18n-html", "logo");
        logo.append(element("div", "logo-mark"), name);
        const tools = element("div", "header-tools");
        const tool = (id, className, iconName, label) => {
            const button = element("button", className);
            button.id = id;
            button.type = "button";
            button.append(icon(iconName));
            button.title = label;
            button.setAttribute("aria-label", label);
            return button;
        };
        if (host.hasAttribute("theme")) tools.append(tool("theme-button", "square", "sun", kitText("theme")));
        if (!host.hasAttribute("no-account")) tools.append(tool("account-button", "ghost square account", "user", kitText("account")));
        if (host.hasAttribute("menu")) {
            const label = host.getAttribute("menu-label") || kitText("menu");
            const withText = host.hasAttribute("menu-text");
            const button = tool("menu-button", withText ? "menu-button" : "ghost square menu-button", "menu", label);
            button.setAttribute("aria-controls", "sidebar");
            button.setAttribute("aria-expanded", "false");
            if (withText) {
                button.removeAttribute("title");
                button.append(element("span", "", label));
            }
            tools.append(button);
        }
        host.id ||= "header";
        host.replaceChildren(logo, tools);
        return ["header"];
    }, { texts: true });

    defineElement("sidebar", ["tablist", "label"], (host, { content, slots }) => {
        const kept = host.querySelector(":scope > #sidebar-nav");   // the app writes in the list: it stays the same element
        const nav = kept ?? element("div", "sidebar-nav");
        nav.id = "sidebar-nav";
        if (host.hasAttribute("tablist")) nav.setAttribute("role", "tablist");
        if (host.getAttribute("label")) nav.setAttribute("aria-label", host.getAttribute("label"));
        if (!kept) nav.append(...content);
        host.id ||= "sidebar";
        host.replaceChildren(...(slots.before ?? []), nav, ...(slots.after ?? []));
        return ["sidebar"];
    });

    defineElement("footer", ["status", "brand"], (host, { refresh }) => {
        const copyright = kitText("copyright").replace("{brand}", host.getAttribute("brand") ?? window.i18n?.brand?.name ?? "");
        if (refresh && host.querySelector(".copyright")) {
            host.querySelector(".copyright").textContent = copyright;
            return host.managed;
        }
        const parts = [];
        if (host.hasAttribute("status")) {
            const status = element("span");
            status.id = "status";
            parts.push(status);
        }
        const link = element("a", "copyright", copyright);
        link.href = "/";
        link.target = "_top";
        parts.push(link);
        host.id ||= "footer";
        // the status line is written by the app: keep what it wrote
        const old = host.querySelector("#status");
        if (old && parts[0]?.id === "status") parts[0] = old;
        host.replaceChildren(...parts);
        return ["footer"];
    }, { texts: true });

    /* the parts that open, the path, the tabs, the pages, the steps, and the notes */
    defineElement("collapsible", ["heading", "open"], (host, { content }) => {
        const toggle = element("button", "section-toggle");
        toggle.type = "button";
        toggle.append(element("span", "", host.getAttribute("heading") ?? ""), icon("chevron-down"));
        const body = element("div", "section-body");
        body.append(...content);
        expand({ toggle, body, open: host.hasAttribute("open") });
        // the attribute follows what the user does, without making the parts again
        toggle.addEventListener("click", () => {
            host.updating = true;
            host.toggleAttribute("open", !body.hidden);
            host.updating = false;
        });
        host.replaceChildren(toggle, body);
        host.parts = { toggle, body };
        return ["collapsible"];
    });

    defineElement("breadcrumbs", [], (host, { content }) => {
        const parts = [];
        content.filter((node) => node.nodeType === 1).forEach((node, index) => {
            node.classList.add("breadcrumb");
            if (index) {
                const separator = icon("chevron-right");
                separator.classList.add("breadcrumb-separator");
                parts.push(separator);
            }
            parts.push(node);
        });
        host.replaceChildren(...parts);
        return ["breadcrumbs"];
    }, { live: (node) => !(node.nodeType === 1 && node.classList.contains("breadcrumb-separator")) });

    defineElement("tabs", ["value"], (host, { content }) => {
        host.setAttribute("role", "tablist");
        const buttons = content.filter((node) => node.nodeType === 1);
        for (const button of buttons) {
            const on = (button.getAttribute("value") ?? button.textContent.trim()) === host.getAttribute("value");
            button.setAttribute("role", "tab");
            button.setAttribute("aria-selected", String(on));
            button.classList.toggle("on", on);
            button.onclick = () => {
                host.value = button.getAttribute("value") ?? button.textContent.trim();
                host.dispatchEvent(new CustomEvent("change", { detail: { value: host.value } }));
            };
        }
        host.replaceChildren(...buttons);
        return ["tabs"];
    });

    defineElement("pagination", ["pages", "page"], (host) => {
        const pages = Math.max(1, Number(host.getAttribute("pages")) || 1);
        const page = Math.min(pages, Math.max(1, Number(host.getAttribute("page")) || 1));
        const go = (value) => {
            host.page = value;
            host.dispatchEvent(new CustomEvent("change", { detail: { page: value } }));
        };
        const button = (label, value, on = false, disabled = false) => {
            const node = element("button", on ? "on" : "", label);
            node.type = "button";
            node.disabled = disabled;
            node.addEventListener("click", () => go(value));
            return node;
        };
        const numbers = [];
        for (let number = 1; number <= pages; number++) if (pages <= 7 || number === 1 || number === pages || Math.abs(number - page) <= 1) numbers.push(number);
        const parts = [button(kitText("previous"), page - 1, false, page === 1)];
        numbers.forEach((number, index) => {
            if (index && number - numbers[index - 1] > 1) parts.push(element("span", "", "…"));
            parts.push(button(String(number), number, number === page));
        });
        parts.push(button(kitText("next"), page + 1, false, page === pages));
        host.replaceChildren(...parts);
        return ["pagination"];
    }, { texts: true });

    defineElement("trace-line", ["icon", "heading", "description", "status"], (host, { content }) => {
        const status = host.getAttribute("status") ?? "";
        const detail = hasContent(content);
        const line = element(detail ? "button" : "div", `trace-line${status ? ` ${status}` : ""}`);
        if (detail) line.type = "button";
        line.append(icon(host.getAttribute("icon") || "file"), element("span", "trace-title", host.getAttribute("heading") ?? ""));
        if (host.getAttribute("description")) line.append(element("span", "trace-description", host.getAttribute("description")));
        const parts = [line];
        if (detail) {
            line.append(icon("chevron-down"));
            const body = element("div", "trace-detail");
            body.append(...content);
            expand({ toggle: line, body, open: false });
            parts.push(body);
        }
        host.replaceChildren(...parts);
        return ["trace-item"];
    });

    defineElement("marker", ["variant", "icon", "status", "shimmer"], (host, { content }) => {
        const variant = host.getAttribute("variant") ?? "";
        const text = element("span", host.hasAttribute("shimmer") ? "shimmer" : "");
        text.append(...content);
        const parts = [];
        if (host.hasAttribute("status")) {
            host.setAttribute("role", "status");
            parts.push(element("span", "spinner"));
        } else if (host.getAttribute("icon")) parts.push(icon(host.getAttribute("icon")));
        parts.push(text);
        host.replaceChildren(...parts);
        return ["marker", variant];
    });

    /* the form: a field with its label and hint, and the search box */
    defineElement("field", ["label", "hint"], (host, { content }) => {
        const control = content.find((node) => node.nodeType === 1 && /^(input|select|textarea|button)$/i.test(node.tagName)) ?? content.find((node) => node.nodeType === 1);
        const parts = [];
        if (host.getAttribute("label")) {
            const label = element("label", "field-label", host.getAttribute("label"));
            if (control) {
                control.id ||= `field-${++counter}`;
                label.htmlFor = control.id;
            }
            parts.push(label);
        }
        parts.push(...content);
        if (host.getAttribute("hint")) parts.push(element("span", "field-hint", host.getAttribute("hint")));
        host.replaceChildren(...parts);
        return ["field"];
    });

    defineElement("search", ["input-id", "placeholder", "aria-label"], (host) => {
        const input = host.querySelector("input") ?? element("input");
        input.type = "search";
        if (host.getAttribute("input-id")) input.id = host.getAttribute("input-id");
        input.placeholder = host.getAttribute("placeholder") ?? "";
        const label = host.getAttribute("aria-label");
        if (label) input.setAttribute("aria-label", label);
        host.replaceChildren(icon("search"), input);
        return ["searchbox"];
    });

    // The same component from a script: components.make("alert", { kind: "error", heading: "Failed" }, ["The text."]).
    function make(name, attributes = {}, children = []) {
        const host = document.createElement(`kit-${name}`);
        for (const [key, value] of Object.entries(attributes)) if (value !== false && value != null) host.setAttribute(key, value === true ? "" : value);
        host.append(...children);
        host.render();
        return host;
    }

    window.components = { element, icon, extensionOf, formatSize, status, drawer, download, expand, menu, popover, closeOverlay: closeOpen, select, otp, resizable, carousel, calendar, chart, dataTable, scroller, questionnaire, make, refreshTexts };
})();


/* ============================================================
   account.js — window.account: GitHub sign-in
   ============================================================ */
// The GitHub sign-in shared by every app (they all run on one origin).
// The account is kept in localStorage under the key "account" as { token, login, name, avatar }.
// Sign in once in any app and every other app, open or opened later, knows it.
// The sign-in is "Sign in with GitHub" (an OAuth App): account.signInWithGitHub() sends the whole page to GitHub, GitHub sends it back to youmu/callback.html,
// and account.finishSignIn() trades the code for a token through the Worker of kancamu-auth (the only place that knows the client secret).
// The token has the scope "repo" (assets/data/auth.js), because the storage of the apps is a private repository of the user.
// A token that GitHub made to expire is not an account any more once it has: the apps ask for the sign-in again.
//
// The sign-in screen, the profile, and the settings of every app are pages of the account app (/youmu), chosen by the query string
// (?page=login, ?page=profile, ?page=settings&app=<app>), so no other web builds its own:
//   account.open()              opens the account app in a dialog over the current page: the profile, or the sign-in when there is no account
//   account.open("settings")    opens a page of it: "login", "profile", or "settings"
//   account.bind(btn)           makes a button with the class "account" open the settings of the app (the profile or the sign-in when the app has none),
//                               and show the avatar when signed in
// An app has one button for all of it. The dialog knows the app that opened it (the first folder of the address, such as muai), so it opens on the settings
// of that app; the sidebar of the account app has the profile and the settings of every other app.
(() => {
    const PAGE = new URL("../../youmu/", import.meta.url).href;
    const KEY = "account";
    const PENDING = "account:pending";   // in sessionStorage: what the callback needs to finish the sign-in that this tab began
    const CONFIG = new URL("../data/auth.js", import.meta.url).href;
    const CALLBACK = new URL("callback.html", PAGE).href;
    const OAUTH_TOKEN = /^gh[ou]_/;   // the token of the sign-in with GitHub (gho_ for an OAuth App)
    const listeners = [];

    // Nothing but the sign-in with GitHub makes an account: a token that is not one of its own (pasted in an older version) is deleted at once
    try {
        const old = JSON.parse(localStorage.getItem(KEY));
        if (old && !OAUTH_TOKEN.test(old.token || "")) localStorage.removeItem(KEY);
    } catch {}

    const read = () => {
        try {
            const saved = JSON.parse(localStorage.getItem(KEY));
            return saved && OAUTH_TOKEN.test(saved.token || "") && !(saved.expiresAt && saved.expiresAt <= Date.now()) ? saved : null;
        } catch {
            return null;
        }
    };

    const notify = () => listeners.forEach((listener) => listener(read()));

    const fail = (code) => Object.assign(new Error(code), { code });

    // PKCE: a secret that only this tab knows (the verifier) and its hash (the challenge) that GitHub keeps, so a stolen code is of no use.
    const base64url = (bytes) => btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
    const randomString = (length) => base64url(crypto.getRandomValues(new Uint8Array(length)));
    const challengeOf = async (verifier) => base64url(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier))));

    // The client id (public), the scope, and the address of the Worker: the local one on localhost, the other everywhere else.
    async function loadConfig() {
        let config;
        try {
            config = (await import(CONFIG)).default;
        } catch {
            throw fail("failed");
        }
        const worker = location.hostname === "localhost" ? config.worker?.local : config.worker?.production;
        if (!config.clientId || !worker) throw fail("config");
        return { clientId: config.clientId, scope: config.scope || "", worker };
    }

    const account = {
        // The signed-in account, or null.
        get: read,

        // Sends the whole page to GitHub (it cannot show its page in a frame, so the dialog of the account is left too).
        // Rejects with an error whose code is "config" (no Worker is set for this address in assets/data/auth.js) or "failed".
        async signInWithGitHub() {
            const config = await loadConfig();
            const state = randomString(24);
            const verifier = randomString(48);
            const challenge = await challengeOf(verifier);
            try {
                sessionStorage.setItem(PENDING, JSON.stringify({ state, verifier, returnTo: window.top.location.href, at: Date.now() }));
            } catch {
                throw fail("failed");
            }
            const url = new URL("https://github.com/login/oauth/authorize");
            url.search = new URLSearchParams({
                client_id: config.clientId,
                redirect_uri: CALLBACK,
                scope: config.scope,
                state,
                code_challenge: challenge,
                code_challenge_method: "S256",
            });
            window.top.location.assign(url.href);
        },

        // The callback page gives the code and the state that GitHub sent back. Resolves with the address to go back to.
        // Rejects with an error whose code is "state" (not the sign-in that this tab began, or too old), "exchange", "config", or "failed".
        async finishSignIn({ code, state }) {
            let pending = null;
            try {
                pending = JSON.parse(sessionStorage.getItem(PENDING));
                sessionStorage.removeItem(PENDING);   // used once
            } catch {}
            if (!pending || !code || !state || state !== pending.state || Date.now() - pending.at > 10 * 60 * 1000) throw fail("state");
            const config = await loadConfig();
            let response;
            try {
                response = await fetch(`${config.worker}/token`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ code, redirect_uri: CALLBACK, code_verifier: pending.verifier }),
                });
            } catch {
                throw fail("failed");
            }
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.access_token) throw fail(data.error === "bad_verification_code" ? "state" : "exchange");
            let user;
            try {
                const profile = await fetch("https://api.github.com/user", {
                    headers: { Authorization: `Bearer ${data.access_token}`, Accept: "application/vnd.github+json" },
                });
                if (!profile.ok) throw new Error("profile");
                user = await profile.json();
            } catch {
                throw fail("failed");
            }
            this.set({
                token: data.access_token,
                login: user.login,
                name: user.name || user.login,
                avatar: user.avatar_url,
                ...(data.expires_in ? { expiresAt: Date.now() + data.expires_in * 1000 } : {}),
            });
            return pending.returnTo || "";
        },

        // Saves an account that an app has already checked itself.
        set(info) {
            try {
                localStorage.setItem(KEY, JSON.stringify(info));
            } catch {}
            notify();
        },

        // Signs out, and takes the token back from GitHub (through the Worker) so that a copy of it stops working too.
        signOut() {
            const saved = read();
            try {
                localStorage.removeItem(KEY);
            } catch {}
            notify();
            if (saved) {
                loadConfig()
                    .then((config) => fetch(`${config.worker}/revoke`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token: saved.token }), keepalive: true }))
                    .catch(() => {});
            }
        },

        // Opens the account app in a dialog (it closes itself). page: "login", "profile", or "settings".
        open(page = "", app = location.pathname.split("/").filter(Boolean)[0] || "") {
            const url = new URL(PAGE);
            if (page) url.searchParams.set("page", page);
            if (app) url.searchParams.set("app", app);
            let dialog = document.querySelector("dialog.account-dialog");
            if (!dialog) {
                const frame = document.createElement("iframe");
                frame.src = url.href;
                dialog = document.createElement("dialog");
                dialog.className = "account-dialog";
                dialog.append(frame);
                dialog.addEventListener("click", (event) => {
                    if (event.target === dialog) dialog.close();
                });
                window.addEventListener("message", (event) => {
                    if (event.origin !== location.origin || event.source !== frame.contentWindow) return;
                    if (event.data?.type === "account:close") dialog.close();
                });
                document.body.append(dialog);
            }
            const frame = dialog.querySelector("iframe");
            if (frame.src !== url.href) frame.src = url.href;
            dialog.showModal();
            frame.contentWindow?.postMessage({ type: "account:focus" }, location.origin);
        },

        // A button with the class "account": it opens the dialog on the settings of this app, and shows the avatar once signed in.
        bind(button) {
            const render = (user) => {
                button.classList.toggle("signed-in", !!user);
                button.style.backgroundImage = user ? `url("${user.avatar}")` : "";
            };
            button.addEventListener("click", () => this.open("settings"));
            this.onChange(render);
            render(read());
        },

        // Runs fn(account) after every change, also one made in another app.
        onChange(fn) {
            listeners.push(fn);
        },
    };

    window.addEventListener("storage", (event) => {
        if (event.key === KEY || event.key === null) notify();
    });

    window.account = account;
})();


/* ============================================================
   settings.js — window.settings: per-app settings in localStorage
   ============================================================ */
// The settings of the apps, shared by every app (they all run on one origin).
// Everything of an app that the user can adjust (except how a list is shown and sorted) is one of its settings, kept in localStorage under "<app>.settings",
// and can be set in the account app (/youmu/?page=settings&app=<app>, opened by the account button of the app). An app has no settings screen of its own,
// but it can keep a control for a setting in its page: the control and the account app write the same settings, and each follows the other.
//   settings.set("muai", values)               saves the settings of the app (the control of an app, and the account app)
//   settings.get("muai", defaults)              the settings of the app: the defaults, over which the saved values
//   settings.onChange("muai", defaults, fn)     runs fn(settings) when the account app saves a change
//   settings.listen("muai", fn)                 runs fn(message) when the account app did something to the data of the app
//                                               (deleted its chats, reset its drive...), so the app shows what is left
// Only the account app calls reset and announce.
(() => {
    const key = (app) => `${app}.settings`;

    const read = (app) => {
        try {
            return JSON.parse(localStorage.getItem(key(app))) || {};
        } catch {
            return {};
        }
    };

    window.settings = {
        get: (app, defaults = {}) => ({ ...defaults, ...read(app) }),

        onChange(app, defaults, fn) {
            window.addEventListener("storage", (event) => {
                if (event.key === key(app) || event.key === null) fn(this.get(app, defaults));
            });
        },

        listen(app, fn) {
            const channel = new BroadcastChannel(`kancamu-${app}`);
            channel.onmessage = (event) => fn(event.data);
        },

        set(app, values) {
            try {
                localStorage.setItem(key(app), JSON.stringify(values));
            } catch {}
            window.dispatchEvent(new CustomEvent("kancamu:settings", { detail: { app } }));   // the "storage" event does not come to the page that wrote
        },
        // The account app only:
        reset(app) {
            try {
                localStorage.removeItem(key(app));
            } catch {}
            window.dispatchEvent(new CustomEvent("kancamu:settings", { detail: { app } }));
        },
        announce(app, message) {
            const channel = new BroadcastChannel(`kancamu-${app}`);
            channel.postMessage(message);
            channel.close();
        },
    };
})();


/* ============================================================
   storage.js — window.storage: GitHub repository storage
   ============================================================ */
// The GitHub storage shared by the apps that keep data for the user (they all run on one origin).
// One private repository named after the brand (<id>-data, with the id of assets/data/brand.js), on its default branch (main).
// Every app has a folder of its own in the folder AppData: AppData/drivemu, AppData/muai, AppData/lingomu, and so on. An app only touches its own folder,
// and the paths that it gives are inside that folder (the folder is added here), so "a.json" of muai is AppData/muai/a.json in the repository.
// The Drive is not the folder of an app: it is the whole repository, as Drivemu shows it like a file explorer (Documents, Images, Videos, and Audio are next to AppData,
// and AppData is a folder like the others in it). storage.drive() opens it, and its paths are the ones of the repository.
//   const store = await storage.connect("muai");           opens the folder of the app, creating the repository when it is not there yet
//   const drive = await storage.drive();                   opens the whole repository (the Drive)
//   const text = await storage.readFile(store, "a.json");  the text of a file of the folder, or null
//   await storage.writeFile(store, "a.json", text);        saves a file of the folder, and gives its new sha
//   await storage.list(store, "folder");                   [{ name, sha }] of a folder inside the folder of the app
//   await storage.tree(store);                             { files: [{ path, size }], truncated } every file of the folder of the app, in every folder
//   await storage.readBinary(store, "a.jpg");              the bytes of a file (a Uint8Array), or null
//   await storage.writeBinary(store, "a.jpg", bytes);      saves bytes
//   await storage.removeFile(store, "a.json");             deletes a file
// store.root is the whole folder of the app in the repository ("AppData/muai", and "" for the Drive), and store.system (for the Drive) the names at the root of the repository
// that are not files that the user made: AppData and README.md, and store.own (for the Drive) the folder of the data of Drivemu itself, AppData/drivemu.
// An app that works with the git data API itself (Drivemu, the reset of the account app) uses them.
// The repository is made without a README: its first commit is the empty file AppData/.gitkeep.
// Two apps may save at the same moment on the same branch: GitHub then answers 409, and a save or a delete is tried again.
// The account (assets/js/account.js) must be signed in.
(() => {
    const BRAND = new URL("../data/brand.js", import.meta.url).href;
    const API = "https://api.github.com";
    const APPS = "AppData";   // the folder that holds the folders of the apps
    const SYSTEM = [APPS, "README.md"];   // at the root of the repository, what is not a file that the user made: the folders of the apps, and the file that GitHub makes
    const TRIES = 4;          // a save that meets another save (409) is tried this many times

    const fail = (code, message = code) => Object.assign(new Error(message), { code });
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const encode = (path) => path.split("/").map(encodeURIComponent).join("/");

    async function call(store, path, options = {}) {
        const response = await fetch(path.startsWith("http") ? path : API + path, {
            cache: "no-store", // the GitHub API replies with max-age=60; without this the browser serves a stale answer
            ...options,
            headers: {
                Authorization: `Bearer ${store.token}`,
                Accept: "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
                ...(typeof options.body === "string" ? { "Content-Type": "application/json" } : {}),
                ...(options.headers || {}),
            },
        });
        if (!response.ok) {
            let message = response.statusText;
            try {
                message = (await response.json()).message || message;
            } catch {}
            throw Object.assign(new Error(message), { status: response.status });
        }
        return response;
    }

    const json = async (store, path, options) => (await call(store, path, options)).json();

    // base64 of bytes
    const bytesToBase64 = (bytes) => {
        let binary = "";
        for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
        return btoa(binary);
    };
    const toBase64 = (text) => bytesToBase64(new TextEncoder().encode(text));

    // The path of a file of the app, as the repository has it
    const inRepo = (store, path) => [store.root, path].filter(Boolean).join("/").replace(/\/+$/, "");
    const contentsUrl = (store, path) => {
        const full = inRepo(store, path);
        return `/repos/${store.owner}/${store.repo}/contents${full ? `/${encode(full)}` : ""}`;
    };

    // The same thing is done again when another save got in first
    async function again(task) {
        for (let attempt = 1; ; attempt++) {
            try {
                return await task();
            } catch (error) {
                if (error.status !== 409 || attempt >= TRIES) throw error;
                await wait(300 * attempt);
            }
        }
    }

    const storage = {
        // Opens the folder of an app. Rejects with an error whose code is "signedOut", "noWrite", or "failed".
        connect(app) {
            return storage.open(app, `${APPS}/${app}`);
        },

        // Opens the whole repository: the Drive, as a file explorer shows it.
        async drive() {
            const store = await storage.open("drivemu", "");
            store.system = SYSTEM;
            store.own = `${APPS}/drivemu`;   // the folder of the data of Drivemu itself (a json file, say): the reset of the Drive deletes it too
            return store;
        },

        async open(app, root) {
            const account = window.account?.get();
            if (!account) throw fail("signedOut");
            const brand = (await import(BRAND)).default;
            const store = { token: account.token, owner: account.login, repo: `${brand.id}-data`, app, root };

            try {
                store.info = await json(store, `/repos/${store.owner}/${store.repo}`);
            } catch (error) {
                if (error.status !== 404) throw error;
                try {
                    store.info = await json(store, "/user/repos", {
                        method: "POST",
                        body: JSON.stringify({ name: store.repo, private: true, description: `${brand.name} data` }),   // no auto_init: GitHub would add a README.md that nobody asked for
                    });
                    await wait(1500); // GitHub needs a moment to set the repository up
                } catch (create) {
                    if (create.status !== 422) throw create;   // the name is taken: another page made the repository a moment ago
                    store.info = await json(store, `/repos/${store.owner}/${store.repo}`);
                }
            }
            if (!store.info.permissions?.push) throw fail("noWrite");
            store.branch = store.info.default_branch || "main";

            await storage.ensureBranch(store);
            return store;
        },

        // The branch has a commit. A repository that was just made is empty, and the git data API (what Drivemu uses for many files at once) does not work in an empty one
        // (it answers 409; GitHub says so and gives the way out, the contents API, in https://docs.github.com/en/rest/guides/using-the-rest-api-to-interact-with-your-git-database):
        // the first commit is made here, through the contents API, with an empty file in AppData (the first file of any app that comes after goes next to it).
        async ensureBranch(store) {
            try {
                await call(store, `/repos/${store.owner}/${store.repo}/git/ref/heads/${encodeURIComponent(store.branch)}`);
            } catch (error) {
                if (error.status !== 404 && error.status !== 409) throw error;
                try {
                    await call(store, `/repos/${store.owner}/${store.repo}/contents/${APPS}/.gitkeep`, { method: "PUT", body: JSON.stringify({ message: "Initialize", content: "" }) });
                } catch (put) {
                    if (put.status !== 422 && put.status !== 409) throw put;   // the file is there: another page made it first
                }
            }
        },

        // The text of a file of the folder, or null when it is not there.
        async readFile(store, path) {
            try {
                const response = await call(store, `${contentsUrl(store, path)}?ref=${encodeURIComponent(store.branch)}`, {
                    headers: { Accept: "application/vnd.github.raw+json" },
                });
                return await response.text();
            } catch (error) {
                if (error.status === 404) return null;
                throw error;
            }
        },

        // The files of a folder inside the folder of the app: [{ name, sha }] (empty when the folder is not there yet).
        async list(store, folder) {
            try {
                const items = await json(store, `${contentsUrl(store, folder)}?ref=${encodeURIComponent(store.branch)}`);
                return Array.isArray(items) ? items.filter((item) => item.type === "file").map(({ name, sha }) => ({ name, sha })) : [];
            } catch (error) {
                if (error.status === 404) return [];
                throw error;
            }
        },

        // Every file of the folder of the app, in every folder, in one call: { files: [{ path, size }], truncated }.
        // The paths are inside the folder of the app. truncated is true when the folder is too big for GitHub to list in one answer.
        async tree(store) {
            const base = `/repos/${store.owner}/${store.repo}/git/trees`;
            if (!store.root) {   // the Drive: the whole repository
                const whole = await json(store, `${base}/${encodeURIComponent(store.branch)}?recursive=1`);
                return { files: whole.tree.filter((item) => item.type === "blob").map(({ path, size }) => ({ path, size })), truncated: !!whole.truncated };
            }
            // the folder of the app is found one folder at a time, so the files of the other apps are not listed with it
            let sha = encodeURIComponent(store.branch);
            for (const name of store.root.split("/")) {
                const level = await json(store, `${base}/${sha}`);
                const next = level.tree.find((item) => item.type === "tree" && item.path === name);
                if (!next) return { files: [], truncated: false };
                sha = next.sha;
            }
            const tree = await json(store, `${base}/${sha}?recursive=1`);
            return { files: tree.tree.filter((item) => item.type === "blob").map(({ path, size }) => ({ path, size })), truncated: !!tree.truncated };
        },

        // The bytes of a file of the folder (a Uint8Array), or null when it is not there.
        async readBinary(store, path) {
            try {
                const response = await call(store, `${contentsUrl(store, path)}?ref=${encodeURIComponent(store.branch)}`, {
                    headers: { Accept: "application/vnd.github.raw+json" },
                });
                return new Uint8Array(await response.arrayBuffer());
            } catch (error) {
                if (error.status === 404) return null;
                throw error;
            }
        },

        // Saves a file of the folder (a new one, or a new version of it). Gives the sha of the new version.
        async writeFile(store, path, text, message = `${store.app}: save ${path}`) {
            return storage.put(store, path, toBase64(text), message);
        },

        async writeBinary(store, path, bytes, message = `${store.app}: save ${path}`) {
            return storage.put(store, path, bytesToBase64(bytes), message);
        },

        async put(store, path, content, message) {
            const url = contentsUrl(store, path);
            return again(async () => {
                let sha;
                try {
                    sha = (await json(store, `${url}?ref=${encodeURIComponent(store.branch)}`)).sha;
                } catch (error) {
                    if (error.status !== 404) throw error;
                }
                const saved = await json(store, url, { method: "PUT", body: JSON.stringify({ message, content, branch: store.branch, ...(sha ? { sha } : {}) }) });
                return saved.content.sha;
            });
        },

        // Deletes a file of the folder (nothing happens when it is not there).
        async removeFile(store, path, message = `${store.app}: delete ${path}`) {
            const url = contentsUrl(store, path);
            await again(async () => {
                let sha;
                try {
                    sha = (await json(store, `${url}?ref=${encodeURIComponent(store.branch)}`)).sha;
                } catch (error) {
                    if (error.status === 404) return;
                    throw error;
                }
                await call(store, url, { method: "DELETE", body: JSON.stringify({ message, sha, branch: store.branch }) });
            });
        },
    };

    window.storage = storage;
})();


/* ============================================================
   transfer.js — window.transfer: drag-and-drop file transfer
   ============================================================ */
// TODO: this file and the main website work around what the browser does not give (see TODO.md, "Retest"). Retest it from time to time, to make it plain.
// Files of the Drive that can be dragged out of an app, with the types of drag that the browsers know.
//  - An image is dragged as a real <img> with the whole image, so the drop area of any app (ours or somebody else's) gets it as a file (dataTransfer.files), like a
//    file of the computer. A page cannot put a file in a drag by itself (Chrome drops it), so the file is given to the browser as an image: an invisible <img> lies over
//    the element, and is the thing that is dragged.
//  - Any other file (a video, a document) is dragged as a link (text/uri-list) to the file, and its name (text/plain). The browsers have no drag that carries such a file
//    to another site; the apps of Kancamu take the link and read the file from it (transfer.take).
// The file has to be there when the drag starts, so it is read from the Drive while the pointer is over the element.
//   transfer.drag(element, source, region)   makes an element draggable as a file; source is { id, name, size, image, load }, or a function that gives it (for a
//                                            viewer that shows one file after another); load() gives the Blob. region is a function that gives the part of the element
//                                            where an image is dragged (the whole element if left out).
//   await transfer.take(event)               the files of a drop: the ones of the computer, an image of the Drive, or a file of the Drive that came as a link
//   The main website is told (a message to the parent page) which file an app drags, and gives it to the app of any tab as a real file (see app.js).
//   transfer.dragging                        true while a file of this page is being dragged (a page does not take its own file)
(() => {
    const LIMIT = 64 * 1024 * 1024;   // a bigger file is not dragged: it would take too long to read before the drag
    const KEPT = 8;                   // how many files stay ready
    const ready = new Map();          // id -> the address of the file
    const reading = new Set();

    const prepare = (source, done) => {
        if (reading.has(source.id) || source.size > LIMIT) return;
        reading.add(source.id);
        Promise.resolve(source.load())
            .then((blob) => {
                ready.set(source.id, URL.createObjectURL(blob));
                while (ready.size > KEPT) {
                    const [oldest, url] = ready.entries().next().value;
                    ready.delete(oldest);
                    URL.revokeObjectURL(url);
                }
                done();
            })
            .catch(() => {})
            .finally(() => reading.delete(source.id));
    };

    const tell = (message) => { if (window.parent !== window) window.parent.postMessage({ type: "kancamu:drag", ...message }, location.origin); };

    window.transfer = {
        dragging: false,

        drag(element, source, region) {
            const current = () => (typeof source === "function" ? source() : source);
            let handle = null;
            const sync = () => {
                const dragged = current();
                element.draggable = !!dragged && !dragged.image;   // a file that is not an image is dragged by the element itself
                if (!dragged || !dragged.image) { handle?.remove(); handle = null; if (dragged && !ready.has(dragged.id)) prepare(dragged, () => {}); return; }
                const host = (region && region()) || element;
                if (!handle || handle.parentNode !== host) {
                    handle?.remove();
                    handle = new Image();
                    handle.alt = "";
                    handle.style.cssText = "position:absolute;inset:0;width:100%;height:100%;opacity:0;pointer-events:none;z-index:1;";
                    if (getComputedStyle(host).position === "static") host.style.position = "relative";
                    host.prepend(handle);
                    handle.addEventListener("dragstart", (event) => {
                        event.dataTransfer.effectAllowed = "copy";
                        event.dataTransfer.setDragImage(host, event.offsetX, event.offsetY);
                        window.transfer.dragging = true;
                    });
                    handle.addEventListener("dragend", () => { window.transfer.dragging = false; });
                }
                if (handle.dataset.id !== dragged.id) { handle.dataset.id = dragged.id; handle.removeAttribute("src"); handle.style.pointerEvents = "none"; }
                const url = ready.get(dragged.id);
                if (url) { if (handle.getAttribute("src") !== url) handle.src = url; handle.style.pointerEvents = "auto"; }
                else prepare(dragged, sync);
            };
            for (const type of ["pointerenter", "pointermove", "focus"]) element.addEventListener(type, sync);
            element.addEventListener("dragstart", (event) => {
                const dragged = current();
                if (event.target !== element || !dragged || dragged.image) return;
                const url = ready.get(dragged.id);
                event.dataTransfer.effectAllowed = "copy";
                event.dataTransfer.setData("text/plain", dragged.name);
                if (url) event.dataTransfer.setData("text/uri-list", `${url}#${encodeURIComponent(dragged.name)}`);
                window.transfer.dragging = true;
                if (url) tell({ on: true, url, name: dragged.name });
            });
            element.addEventListener("dragend", () => { window.transfer.dragging = false; tell({ on: false }); });
        },

        take(event) {
            const data = event.dataTransfer;
            const files = [...data.files];
            const link = data.getData("text/uri-list").split("\n").find((line) => line && !line.startsWith("#")) || "";   // read now: a drop gives its data only while it is handled
            if (files.length || !link.startsWith(`blob:${location.origin}/`)) return Promise.resolve(files);
            const name = decodeURIComponent(link.split("#")[1] || "file");
            return fetch(link).then((response) => response.blob()).then((blob) => [new File([blob], name, { type: blob.type })]).catch(() => []);
        },
    };
})();

